import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom'; // Импорт Link
import { ArrowUpRight, Image as ImageIcon } from 'lucide-react';
import './BentoHero.css';

const BentoHero = ({ language }) => {
  const [bgIndex, setBgIndex] = useState(0);
  const publicUrl = process.env.PUBLIC_URL || '';

  const bgImages = [
    `${publicUrl}/images/bg-1.jpg`, `${publicUrl}/images/bg-2.jpg`,
    `${publicUrl}/images/bg-3.jpg`, `${publicUrl}/images/bg-4.jpg`,
    `${publicUrl}/images/bg-5.jpg`, `${publicUrl}/images/bg-6.jpg`,
    `${publicUrl}/images/bg-7.jpg`, `${publicUrl}/images/bg-8.jpg`
  ];

  // Исправленный баг таймера: добавляем bgIndex в зависимости
  useEffect(() => {
    const interval = setInterval(() => {
      setBgIndex((prevIndex) => (prevIndex + 1) % bgImages.length);
    }, 15000); 
    return () => clearInterval(interval);
  }, [bgIndex, bgImages.length]);

  const nextBg = (e) => {
    e.preventDefault();
    setBgIndex((prevIndex) => (prevIndex + 1) % bgImages.length);
  };

  const handleMouseMove = (e) => {
    const card = e.currentTarget;
    const rect = card.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;
    const rotateX = ((y - centerY) / centerY) * -6; 
    const rotateY = ((x - centerX) / centerX) * 6;
    card.style.transition = 'none';
    card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale3d(1.02, 1.02, 1.02)`;
  };

  const handleMouseLeave = (e) => {
    const card = e.currentTarget;
    card.style.transition = 'transform 0.5s cubic-bezier(0.25, 1, 0.5, 1)'; 
    card.style.transform = `perspective(1000px) rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)`;
  };

  const content = {
    RU: {
      tags: ['О ПРОЕКТЕ', 'СТУДЕНТАМ', 'ТЮМГУ'],
      title: 'ТЮМЕНЬ',
      subtitle: 'первый русский город Сибири',
      introTitle: 'ПОГРУЗИСЬ В АТМОСФЕРУ ГОРОДА',
      introDesc: 'ВМЕСТЕ С НАМИ',
      mapTitle: 'Интерактивная карта',
      mapDesc: 'локаций'
    },
    EN: {
      tags: ['ABOUT PROJECT', 'FOR STUDENTS', 'UTMN'],
      title: 'TYUMEN',
      subtitle: 'the first Russian city in Siberia',
      introTitle: 'IMMERSE YOURSELF IN THE CITY',
      introDesc: 'ATMOSPHERE WITH US',
      mapTitle: 'Interactive map',
      mapDesc: 'of locations'
    }
  };

  const data = content[language];

  return (
    <section className="bento-hero-section">
      <div className="container">
        <div className="bh-hero-container">
          <div className="bh-hero-bg-container">
            {bgImages.map((img, idx) => (
              <div 
                key={idx}
                className={`bh-hero-bg ${idx === bgIndex ? 'active' : ''}`}
                style={{ backgroundImage: `linear-gradient(to bottom, rgba(0,0,0,0.4) 0%, rgba(0,0,0,0.1) 40%, rgba(0,0,0,0.6) 100%), url('${img}')` }}
              />
            ))}
          </div>

          <button className="bh-change-bg-btn" onClick={nextBg}>
            <ImageIcon size={16} />
            <span>{language === 'RU' ? 'Сменить фото' : 'Next photo'}</span>
          </button>

          <div className="bh-hero-top-tags">
            <div className="bh-top-tag accent">{data.tags[0]}</div>
            <div className="bh-top-tag">{data.tags[1]}</div>
            <div className="bh-top-tag">{data.tags[2]}</div>
          </div>

          <div className="bh-hero-title-wrapper">
            <h1 className="bh-title">{data.title}</h1>
            <p className="bh-subtitle">{data.subtitle}</p>
          </div>

          <div className="bh-hero-intro">
            <h2>{data.introTitle}<br/>{data.introDesc}</h2>
          </div>

          {/* Заменили <a> на <Link> */}
          <Link 
            to="/map" 
            id="tour-map"
            className="bh-glass-card"
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
          >
            <div className="bh-glass-text">
              <span className="bh-glass-title">{data.mapTitle}</span>
              <span className="bh-glass-desc">{data.mapDesc}</span>
            </div>
            <div className="bh-glass-btn">
              <ArrowUpRight size={20} strokeWidth={2.5} color="#000" />
            </div>
          </Link>
        </div>
      </div>
    </section>
  );
};

export default BentoHero;